from taf.sbts.oam.coam.admin.interfaces.admin_26r1 import SBTS26R1
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable


class SBTS26R2(SBTS26R1):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS26R2, self).__init__(api_client)

    def switch_role(self, wait_for_reconnection=True, timeout=100, detailed_output=False):
        """
        Switch role function.

        .. note::
            SUPPORTS CUSTOMER API ONLY

        :param bool wait_for_reconnection: (Optional) Wait for reconnection - default value: True.
        :param int timeout: Timeout for the operation, default set to 100 seconds.
        :param bool detailed_output: Return full request response when True, default set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-roleSwitch.html
        """
        parameters = {'waitForReconnection': wait_for_reconnection}
        response = self._api_client.execute_customer_procedure('roleSwitch', parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_secondary_core(self, timeout=120, detailed_output=False):
        """
        Reset Secondary Core - introduced for CB013223.

        .. note::
            SUPPORTS CUSTOMER API ONLY

        :param int timeout: (Optional) Timeout for the operation, default set to 120s.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return Union[list,dict]: Reset cell feedback info or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """
        parameters = {'resetCoverage': 'SecondaryCore'}
        response = self._api_client.execute_customer_procedure('reset', parameters, timeout)
        if response is None:
            raise DataNotAvailable("ResetSecondaryCore data has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)
